+      expect(parsed.content, fixture.id).toBe("");
+    }
+  });
+
+  test("rejects browser OpenUI source without evaluating it on-device", () => {
+    const globalScope = globalThis as typeof globalThis & { __keatingOpenUiExecuted?: boolean };
